-- Curated game prototypes are separate from real collection identity and profile instances.
CREATE TABLE game_collection_definitions(game_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL REFERENCES object_categories(id), rarity TEXT NOT NULL CHECK(rarity IN('COMMON','UNCOMMON','RARE','TREASURE')), base_value INTEGER NOT NULL CHECK(base_value>0), inventory_slots INTEGER NOT NULL CHECK(inventory_slots>=1), exhibit_appeal INTEGER NOT NULL CHECK(exhibit_appeal>=0), unlock_conditions TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(unlock_conditions)), game_asset_id TEXT, approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN(0,1)), available_world_year INTEGER, acquisition_mode TEXT NOT NULL DEFAULT 'UNREVIEWED' CHECK(acquisition_mode IN('UNREVIEWED','FICTIONAL_TOMB_ARCHETYPE','HISTORICALLY_KNOWN','FICTIONAL_EXPEDITION')), world_reviewed INTEGER NOT NULL DEFAULT 0 CHECK(world_reviewed IN(0,1)), world_review_note TEXT NOT NULL DEFAULT '', transport_mode TEXT NOT NULL DEFAULT 'HAND_CARRY' CHECK(transport_mode IN('HAND_CARRY','EXPEDITION_TRANSPORT')), legacy_resource_path TEXT, curator_locked INTEGER NOT NULL DEFAULT 1 CHECK(curator_locked IN(0,1)));
CREATE TABLE game_object_references(game_id TEXT NOT NULL REFERENCES game_collection_definitions(game_id), object_id TEXT NOT NULL REFERENCES collection_objects(object_id), relation TEXT NOT NULL CHECK(relation IN('FORM_REFERENCE','HISTORICAL_REFERENCE','SPECIMEN_REFERENCE')), review_note TEXT NOT NULL, PRIMARY KEY(game_id,object_id));
CREATE TABLE game_obtain_regions(game_id TEXT NOT NULL REFERENCES game_collection_definitions(game_id), region_id TEXT NOT NULL REFERENCES regions(id), PRIMARY KEY(game_id,region_id));
CREATE INDEX game_approval ON game_collection_definitions(approved,available_world_year);
ALTER TABLE media ADD COLUMN local_asset_path TEXT;
